fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo, choose 'Testing', then click the 'Review' tab. Then perform these sub-actions IN ORDER, and as you complete each set \"checkpointReached\" to the exact checkpoint name shown: (1) review-queue-submission — the Human Review view shows a KPI summary row and a Review Queue; if pending accordion items exist, expand one, pick a Rating number, click a correctness button (Correct or Incorrect), optionally type a note, then click Submit and confirm the item is accepted (it leaves the queue or shows a submitted state); if the queue is empty, confirming the 'All caught up!' empty state renders correctly is also success; (2) review-history-toggle — near the top there is a view toggle with 'Review Queue' and 'History' buttons; click 'History' and confirm the content switches to the reviewed/history view, then click 'Review Queue' to switch back (each view shows content or a valid empty state). Keep going until both sub-actions are done. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200/app/testing",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "review-queue-submission",
      "instruction": "reach Review tab; submit a review or confirm empty-state",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/testing"
        }
      ],
      "visualCriteria": [
        "The Review tab shows a KPI summary row and a Review Queue; if items exist, expanding one reveals a rating scale, correctness buttons, and a notes field and Submit removes/updates the item once a rating/correctness is chosen; if empty, the 'All caught up!' empty-state renders cleanly"
      ]
    },
    {
      "name": "review-history-toggle",
      "instruction": "toggle between Review Queue and History views",
      "visualCriteria": [
        "The Review tab shows a Review Queue / History view toggle; clicking History switches to the history view and clicking Review Queue switches back, each rendering its content or a valid empty state"
      ]
    }
  ]
}
